<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Models\User; use App\Models\Role; use Illuminate\Http\Request; use Illuminate\Support\Facades\Hash;
class UserController extends Controller { public function index(Request $r){return User::where('company_id',$r->user()->company_id)->with('roles')->latest()->paginate($r->integer('per_page',30));} public function store(Request $r){$d=$r->validate(['name'=>'required|string|max:255','email'=>'required|email|unique:users,email','password'=>'required|min:8','branch_id'=>'nullable|exists:branches,id','role'=>'required|string']);$company=$r->user()->company_id;abort_unless(Role::where('name',$d['role'])->exists(),422,'Invalid role.');if(!empty($d['branch_id']))abort_unless(\App\Models\Branch::where('company_id',$company)->whereKey($d['branch_id'])->exists(),422,'Invalid branch.');$u=User::create(['company_id'=>$company,'branch_id'=>$d['branch_id']??$r->user()->branch_id,'name'=>$d['name'],'email'=>$d['email'],'password'=>Hash::make($d['password']),'is_active'=>true]);$u->assignRole($d['role']);return response()->json($u->load('roles','branch'),201);} public function update(Request $r,User $user){abort_unless($user->company_id===$r->user()->company_id,404);$d=$r->validate(['name'=>'required|string|max:255','branch_id'=>'nullable|exists:branches,id','role'=>'required|string','is_active'=>'boolean']);$u=$d['role'];unset($d['role']);$user->update($d);$user->syncRoles([$u]);return $user->fresh()->load('roles','branch');} public function destroy(Request $r,User $user){abort_unless($user->company_id===$r->user()->company_id,404);if($user->id===$r->user()->id)return response()->json(['message'=>'You cannot deactivate your own account.'],422);$user->update(['is_active'=>false]);return response()->noContent();} public function roles(){return Role::where('guard_name','web')->orderBy('name')->get(['id','name']);} }
